import sys
import json

def calculate_revenue(prices, quantities):
    """Calculate per-item revenues and total revenue.

    Args:
        prices (list of numbers): unit prices for items
        quantities (list of numbers): sold quantities for items

    Returns:
        dict: {"per_item": [...], "total": <number>}
    """
    if not isinstance(prices, list) or not isinstance(quantities, list):
        raise TypeError("prices and quantities must be lists")
    if len(prices) != len(quantities):
        raise ValueError("prices and quantities must have the same length")
    per_item = []
    for p, q in zip(prices, quantities):
        try:
            per_item.append(p * q)
        except Exception:
            raise TypeError("prices and quantities must contain numeric values")
    total = sum(per_item)
    return {"per_item": per_item, "total": total}


def main():
    """Read JSON from stdin with keys 'prices' and 'quantities', write JSON result to stdout."""
    data = json.load(sys.stdin)
    prices = data.get("prices", [])
    quantities = data.get("quantities", [])
    result = calculate_revenue(prices, quantities)
    json.dump(result, sys.stdout)


if __name__ == "__main__":
    main()

