#!/usr/bin/env python3
"""
Compute total revenue from stdin lines. Accepts lines of the form:
 - "price quantity"
 - "price,quantity"
 - "price\tquantity"
Or a single number per line which is treated as price with quantity 1.
Ignores empty or unparsable lines. Prints total revenue as a float with two decimals.
"""
import sys

def parse_line(line):
    line = line.strip()
    if not line:
        return None
    # Try common separators
    for sep in (',', '\t', ' '):
        if sep in line:
            parts = [p for p in line.split(sep) if p != '']
            if len(parts) >= 2:
                try:
                    return float(parts[0]), float(parts[1])
                except ValueError:
                    return None
    # If no separator found, try single number as price with quantity 1
    try:
        return float(line), 1.0
    except ValueError:
        return None


def main():
    total = 0.0
    for line in sys.stdin:
        parsed = parse_line(line)
        if parsed:
            price, qty = parsed
            total += price * qty
    # Print total revenue with two decimal places
    print(f"{total:.2f}")

if __name__ == '__main__':
    main()

